fn decode_checkpoint_box(bytes: &[u8]) -> Result<Box<PoolV1PairForestCheckpointV1>, ProgramError> {
    let raw = decode_pool_v1_pair_forest_checkpoint_v1(bytes);
    let mut out = (|| { Ok(Box::new(raw.map_err(|_| ProgramError::InvalidAccountData)?)) })();
    #[cfg(kani)] {
        let j:usize=kani::any();kani::assume(j<32);
        kani::assume(raw.is_ok());if let Ok(ref mut b)=out{b.master[j] ^= 1;}
        let good=match (&raw,&out) {(Ok(a),Ok(b))=>a.master[j]==b.master[j],(Err(_),Err(e))=>*e==ProgramError::InvalidAccountData,_=>false};
        assert!(good, "actual wrapper returned field/error at SAME raw decoder call");
    }
    out
}
